import { CHECKLIST, S1, S2, S3, S4, S5, SCENES, absFrame } from "./timing";

// Audio integration points. Each cue is a separate file in public/audio/
// (generated by scripts/generate_audio.py) so any of them can be replaced by a
// licensed library sound without touching the scenes. Every cue must end
// before SILENT_FROM (frame 885) so the last 0.5 s is silent.

export type AudioCue = {
  id: string;
  src: string;
  from: number; // absolute frame
  durationInFrames: number; // file length, used to verify the silent tail
  volume: number;
};

